import{_ as e,o as a,c as o,ai as r}from"./chunks/framework.scx6l_IK.js";const u=JSON.parse('{"title":"金刚经22分-无法可得","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/金刚经22分-无法可得.md","filePath":"60-原文段落/金刚经22分-无法可得.md","lastUpdated":1778155802000}'),_={name:"60-原文段落/金刚经22分-无法可得.md"};function p(s,t,n,c,d,i){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="金刚经22分-无法可得" tabindex="-1">金刚经22分-无法可得 <a class="header-anchor" href="#金刚经22分-无法可得" aria-label="Permalink to &quot;金刚经22分-无法可得&quot;">​</a></h1><blockquote><p>来源：<a href="/01-Raw-Sources/22了空居士讲《金刚经》-第二十二分无法可得分20170224">22了空居士讲《金刚经》-第二十二分无法可得分20170224</a> 切分日期：2026-05-06</p></blockquote><hr><p><strong>我于阿耨多罗三藐三菩提，乃至无有少法可得，是名阿耨多罗三藐三菩提。</strong></p><p>他就说，须菩提啊，我证这个阿耨多罗三藐三菩提不仅仅是没有一个具体的阿耨多罗三藐三菩提的法，就算一点点的法都没有啊，我是彻底的无所得啊，心里清清净净的。乃至的意思就是加深，就连一点点都没有，这个就是程度上的加深，乃至，就算一点点都没有的。</p><p>是名，这里他就是继续解释，我所说的这个阿耨多罗三藐三菩提只是一个虚名而已呀，只是一个名称。好像有一首偈&quot;因缘所生法，我说即是空，是名为假名，亦是中道义&quot;，这首偈很著名的，就是讲这个意思，就说我说阿耨多罗三藐三菩提，其实啊，说我证得阿耨多罗三藐三菩提就根本没有一个具体的东西叫做阿耨多罗三藐三菩提，不要说很具体，就是一点点都没有。那么我老是说那个阿耨多罗三藐三菩提又是什么意思呢？只是不得已取了这个名而已，实际上是真真正正证得这个心啦无所执着，就像《金刚经》前边说&quot;应无所住而生其心&quot;，是这个意思。</p><hr><p><strong>佛祖的无所得：无有定法名阿耨多罗三藐三菩提</strong></p><p>其实《金刚经》里边说&quot;无有定法名阿耨多罗三藐三菩提&quot;，没有一个固定的方法。既然没有固定的，一切都是刹那变化的，你能说你得到了吗？是不是啊？所以说就是没有一个固定的东西，其实吧也就是说这个阿耨多罗三藐三菩提能够证悟这个境界的人，他的心特别清净，一切善恶，一切爱憎他都不执着，他的心永远是清醒的，他遇到事情就是以这个非常清醒的心态去具体问题具体分析，这种人就称为证得阿耨多罗三藐三菩提，大概是这个意思，没有一个具体的东西的。</p><p>佛祖他是成就了阿耨多罗三藐三菩提，然后告诉我们无所得，那么他又有成就又无所得，是什么意思呢？他无所得任何一个固定的法，成就了一个绝对的清净心。绝对的清净心在哪里？就是在一切的情境之下，你都不着相，是不是啊，就是应无所住而生其心，离一切相则名诸佛，在顺境你不贪着，逆境你不嗔恚，你的心永远就是如如不动。他不是什么都不知道，他是什么都知道，但是不会受影响。所以佛祖的无所得是一切法他无所得，无所执着，但是你说他得到一个最清净的心呢，其实也不对，因为他没有一个绝对的清净心，他只是在一切的情境下他不受干扰，是这个意思。</p><p>那我们在阿耨多罗三藐三菩提无所得是我们没有证得，也就是说我们还没有证得在一切情境下你的心都能够不受干扰，如如不动，一切了了分明。但是如如不动，正如六祖说的大圆镜智，也就说我什么都知道的，但是我不会动摇，我们无所得是没有证得这种如如不动的清净心，佛祖的无所得是对万法无所执着。这个有所不同，我们对万法反而是有所得了，有所执着了，我们没有证得如如不动的清净心，但是对一切万相会产生执着，佛祖就反过来，对一切万法、一切现象无所执着，他的心如如不动，正好跟我们就是这么不同。</p>',11)])])}const f=e(_,[["render",p]]);export{u as __pageData,f as default};
